import{_ as e,o as r,c as a,a as o}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const p=JSON.parse('{"title":"CV","description":"Олег Сидоркин — Engineering Manager и System Architect, Казань. 21 год в ИТ: 13 лет разработки, 8 лет руководства. AI-системы, Go, WebGPU, аудит архитектуры.","frontmatter":{"site":"pro","title":"CV","description":"Олег Сидоркин — Engineering Manager и System Architect, Казань. 21 год в ИТ: 13 лет разработки, 8 лет руководства. AI-системы, Go, WebGPU, аудит архитектуры.","aside":false,"outline":false,"head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/cv"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"CV"}],["meta",{"property":"og:description","content":"Олег Сидоркин — Engineering Manager и System Architect, Казань. 21 год в ИТ: 13 лет разработки, 8 лет руководства. AI-системы, Go, WebGPU, аудит архитектуры."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/cv"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"CV"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — Engineering Manager и System Architect, Казань. 21 год в ИТ: 13 лет разработки, 8 лет руководства. AI-системы, Go, WebGPU, аудит архитектуры."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"cv.md","filePath":"cv.md"}'),n={name:"cv.md"};function i(l,t,s,d,g,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="олег-сидоркин" tabindex="-1">Олег Сидоркин <a class="header-anchor" href="#олег-сидоркин" aria-label="Permalink to &quot;Олег Сидоркин&quot;">​</a></h1><p><strong>Engineering Manager · System Architect · Руководитель разработки</strong></p><p>Казань · удалённо, полная занятость · <a href="mailto:osidorkin85@gmail.com" target="_blank" rel="noreferrer">osidorkin85@gmail.com</a> · <a href="https://github.com/alterfo" target="_blank" rel="noreferrer">github.com/alterfo</a> · <a href="https://t.me/osidorkin85" target="_blank" rel="noreferrer">@osidorkin85</a></p><p>21 год в ИТ: 13 лет коммерческой разработки, 8 из них руководство. Ищу узкое место в системе и снимаю причину, а не симптом. Пишу код сам, поэтому совет не расходится с тем, что выполнимо руками.</p><h2 id="коротко" tabindex="-1">Коротко <a class="header-anchor" href="#коротко" aria-label="Permalink to &quot;Коротко&quot;">​</a></h2><p>Начинал с эксплуатации: ITSM, мониторинг, SLA 99.999%, дежурства on-call. Дальше 13 лет разработки, восемь из них техническое руководство: группы до 30 инженеров, ассессмент, менторинг, стандарты, онбординг. Разбираю узкие места и в процессе, и в коде: тестовый стенд, который лежал 80% времени, e2e-прогон на 20 минут вместо полутора часов, 80% медленных запросов к базе. Продукты выводил в прод и вёл после релиза: логи, метрики, SLA, инциденты, AppSec.</p><h2 id="чем-занимаюсь" tabindex="-1">Чем занимаюсь <a class="header-anchor" href="#чем-занимаюсь" aria-label="Permalink to &quot;Чем занимаюсь&quot;">​</a></h2><ul><li><strong>AI-системы до продакшена.</strong> RAG с графом знаний, верификация фактов, прогон через открытые бенчмарки, а не по ощущению «вроде работает».</li><li><strong>Алго-трейдинг.</strong> Данные, признаки, ансамбль моделей, риск-гейты, ньюс-вето.</li><li><strong>Архитектура и производительность.</strong> Разбор платформ по шести доменам, дорожная карта и цена бездействия — см. <a href="/audit/">аудит</a>.</li><li><strong>Фронтенд и дизайн-системы.</strong> Корпоративные компоненты, low-code, миграции без остановки продукта.</li></ul><h2 id="публичные-проекты" tabindex="-1">Публичные проекты <a class="header-anchor" href="#публичные-проекты" aria-label="Permalink to &quot;Публичные проекты&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Проект</th><th>Что это</th><th>Доказательство</th></tr></thead><tbody><tr><td><strong>kb</strong></td><td>RAG-движок: гибридный поиск, временной граф знаний, слой верификации. Первое место в русскоязычном RAG Leaderboard</td><td><a href="https://github.com/alterfo/kb" target="_blank" rel="noreferrer">github.com/alterfo/kb</a></td></tr><tr><td><strong>Approximate</strong></td><td>Алго-трейдер: Go, LightGBM + XGBoost, риск-гейты, ньюс-вето. Проверено 46 направлений на данных 2021–2026</td><td><a href="https://github.com/alterfo/moex-trader" target="_blank" rel="noreferrer">moex-trader</a>, <a href="https://zenodo.org/records/24111519" target="_blank" rel="noreferrer">исследование AlgoPack и MOEX</a></td></tr><tr><td><strong>FinContext MCP</strong></td><td>Финансовый контекст для AI-ассистента бизнеса, self-hosted в облаке клиента</td><td><a href="https://github.com/alterfo/fincontext-mcp" target="_blank" rel="noreferrer">fincontext-mcp</a></td></tr><tr><td><strong>IDEF0 Editor</strong></td><td>Редактор функциональных диаграмм по FIPS 183, валидация ICOM на лету</td><td><a href="/idef0.html">/idef0</a>, <a href="/projects/idef0-editor.html">разбор</a></td></tr><tr><td><strong>Shelfprice</strong></td><td>Аудит ценников с локальной vision-моделью, экспорт в 1С</td><td>локальный проект</td></tr></tbody></table><h2 id="навыки" tabindex="-1">Навыки <a class="header-anchor" href="#навыки" aria-label="Permalink to &quot;Навыки&quot;">​</a></h2><p><strong>AI и LLM:</strong> Advanced RAG, GraphRAG, logicRAG, MCP, Graph of Thoughts, LlamaIndex, мультиагентная оркестрация, векторные базы данных, OpenSearch, оценка качества retrieval.</p><p><strong>ML и исследования:</strong> TimesFM 3, Ridge-регрессия, временные ряды, новостные потоки, Python, WebGPU, Wasm, on-device ML.</p><p><strong>Инженерия:</strong> Go, TypeScript, JavaScript, Vue 3, React, Node.js, PostgreSQL, MongoDB, SQLite, Redis, Kafka, Kubernetes, Docker, Terraform, Yandex Cloud (Functions, API Gateway, YDB, Lockbox), CI/CD, Playwright, CODEOWNERS, монорепозитории, e2e-тесты, SAST/SCA, Grafana, Sentry, RFC-процесс, code review, on-call, ITIL/ITSM.</p><p><strong>Руководство:</strong> собеседования и оценка кандидатов, менторинг, онбординг, ИПР, обучение интервьюеров, ассессмент, технические стандарты, фасилитация.</p><h2 id="образование" tabindex="-1">Образование <a class="header-anchor" href="#образование" aria-label="Permalink to &quot;Образование&quot;">​</a></h2><ul><li><strong>ИЭУП (IEML)</strong> — бакалавр, информационная безопасность телекоммуникационных систем.</li><li>Project Management, Google.</li><li>Startup Engineering, Stanford.</li></ul><h2 id="контакты" tabindex="-1">Контакты <a class="header-anchor" href="#контакты" aria-label="Permalink to &quot;Контакты&quot;">​</a></h2><p>Почта: <a href="mailto:osidorkin85@gmail.com" target="_blank" rel="noreferrer">osidorkin85@gmail.com</a> Telegram: <a href="https://t.me/osidorkin85" target="_blank" rel="noreferrer">@osidorkin85</a> GitHub: <a href="https://github.com/alterfo" target="_blank" rel="noreferrer">github.com/alterfo</a></p><p>Резюме в PDF и рекомендации — по запросу.</p>',20)])])}const m=e(n,[["render",i]]);export{p as __pageData,m as default};
